#[test]
fn from_str_base_unit() {
    let abbr = MassConcentrationUnit::KilogramPerCubicMeter.abbreviation();
    let s = format!("1 {}", abbr);
    let parsed: MassConcentration = s.parse().expect("parse failed");
    let expected = MassConcentration::from_kilograms_per_cubic_meter(1.0).as_base();
    assert!((parsed.as_base() - expected).abs() / expected.abs().max(1.0) < RT_EPS);
}
